from collections import deque

def bfs_depth_n(graph, start, target_depth):
    # Returns nodes at exactly target_depth from start
    # Depth 0 is start node itself
    if target_depth == 0:
        return [start]

    visited = set([start])
    queue = deque([(start, 0)])
    nodes_at_target_depth = set()

    while queue:
        node, depth = queue.popleft()

        if depth == target_depth:
            nodes_at_target_depth.add(node)
            continue  # Don't expand nodes at target depth

        if depth < target_depth:
            for neighbor in graph.get(node, []):
                if neighbor not in visited or depth + 1 == target_depth:
                    # For BFS at exact depth, we need to allow revisiting if it leads to target depth
                    # But we track by (node, depth) to avoid infinite loops
                    queue.append((neighbor, depth + 1))

    return sorted(list(nodes_at_target_depth))

